package com.blockworld.core;

/** Biomes found below the surface in worlds generated by version 1.9.6 and newer. */
public enum CaveBiomeType {
    NONE("Обычная пещера"),
    CRYSTAL_GROTTO("Кристальный грот"),
    MOSS_CAVERN("Мшистая пещера"),
    UNDERGROUND_LAKE("Подземное озеро");

    private final String displayName;

    CaveBiomeType(String displayName) {
        this.displayName = displayName;
    }

    public String displayName() {
        return displayName;
    }
}
